msg.payload = '<img src="data:image/jpeg;base64,' 
              + msg.payload 
              + '" style="width:100%;height:auto;"/>';
return msg;

var data = msg.payload;
if (typeof data === "string") {
    try { data = JSON.parse(data); } catch (e) { return null; }
}

var p = data.proprietaire || {};
var date = (data.horodatage || "").replace("T", " ").substring(0, 19);
var plaqueLue = data.plaque && data.plaque !== "INCONNUE";
var html;

if (!data.erreur) {
    // Toute infraction reçue s'affiche en rouge, plaque lue ou non
    var titre = String(data.type || "SENS INTERDIT").replace(/_/g, " ").toUpperCase();

    html = "<div class='anpr-card infraction'>" +
        "<div class='titre'>⛔ " + titre + "</div>" +
        "<div class='plaque'>" + (plaqueLue ? data.plaque : "PLAQUE NON LUE") + "</div>" +
        "<table>" +
        "<tr><td>Date</td><td>" + (date || "-") + "</td></tr>";

    if (plaqueLue) {
        html += "<tr><td>Carte grise</td><td>" + (p.carte_grise || "-") + "</td></tr>" +
            "<tr><td>Propriétaire</td><td>" + (p.nom || "-") + " " + (p.prenom || "") + "</td></tr>" +
            "<tr><td>E-mail</td><td>" + (p.email || "-") + "</td></tr>" +
            "<tr><td>Tél</td><td>" + (p.telephone || "-") + "</td></tr>";
    } else {
        html += "<tr><td>Propriétaire</td><td>Inconnu : vérification manuelle de la preuve</td></tr>";
    }
    html += "</table></div>";
} else {
    // Vraie erreur (message invalide, pas une infraction)
    html = "<div class='anpr-card erreur'>" +
        "<div class='titre'>⚠ ERREUR</div>" +
        "<div>" + data.erreur + "</div></div>";
}

msg.payload = html;
return msg;

try {
    var output = cp.execSync(
        'python C:/projet_anpr/test/export_csv.py',
        { encoding: 'utf8', timeout: 10000 }
    );
    msg.payload = output;
} catch (e) {
    msg.payload = "horodatage,plaque,type\nErreur," + e.message.substring(0, 200);
}

msg.headers = {
    'Content-Type': 'text/csv; charset=utf-8',
    'Content-Disposition': 'attachment; filename="infractions.csv"'
};
msg.statusCode = 200;
return msg;

var st = context.get('st') || {temp:null,hum:null,gaz:null,dist:null,alerte:false,ir:false,buzzer:false,img:'',inf:null,ts:0,lat:null,lng:null,speed:null,fix:false,infSeq:0};
var t = msg.topic;
var p = msg.payload;
if (Buffer.isBuffer(p)) p = p.toString();

if      (t === 'DATA/TEMP')       st.temp   = parseFloat(p);
else if (t === 'DATA/HUM')        st.hum    = parseFloat(p);
else if (t === 'DATA/GAZ')        st.gaz    = parseFloat(p);
else if (t === 'DATA/DIST')       st.dist   = parseFloat(p);
else if (t === 'DATA/GAZ_ALERTE') st.alerte = String(p).trim() === '1';
else if (t === 'DATA/IR')         st.ir     = String(p).trim() === '1';
else if (t === 'DATA/GPS') {
    var s = String(p).trim();
    var parts = s.split(',');
    var la = parseFloat(parts[0]), lo = parseFloat(parts[1]);
    if (parts.length === 2 && !isNaN(la) && !isNaN(lo)) { st.lat = la; st.lng = lo; st.fix = true; }
    else { st.fix = false; }
}
else if (t === 'DATA/GPS_SPEED')  { var sp = parseFloat(p); st.speed = isNaN(sp) ? null : sp; }
else if (t === 'DATA/BUZZER')     st.buzzer = String(p).trim() === '1';
else if (t === 'ANPR/camera/frame') {
    var b = String(p).trim();
    st.img = b.indexOf('data:') === 0 ? b : 'data:image/jpeg;base64,' + b;
} else if (t === 'ANPR/infraction') {
    var d = p;
    if (typeof d === 'string') { try { d = JSON.parse(d); } catch(e){ return null; } }
    if (!d || typeof d !== 'object') return null;
    st.infSeq = (st.infSeq || 0) + 1;
    if (d.erreur) {
        st.inf = {erreur: String(d.erreur)};
    } else {
        var o = d.proprietaire || {};
        var connue = !!d.plaque && d.plaque !== 'INCONNUE';
        /* Lieu de l'infraction : fourni par le script ANPR, sinon dernière position GPS reçue */
        var L = d.localisation || d.location || {};
        var la = parseFloat(L.lat !== undefined ? L.lat : (d.latitude !== undefined ? d.latitude : d.lat));
        var lo = parseFloat(L.lng !== undefined ? L.lng : (L.lon !== undefined ? L.lon : (d.longitude !== undefined ? d.longitude : d.lng)));
        if (isNaN(la) || isNaN(lo)) {
            if (st.fix && typeof st.lat === 'number' && typeof st.lng === 'number') { la = st.lat; lo = st.lng; }
            else { la = null; lo = null; }
        }
        var adr = String(L.adresse || L.address || d.adresse || '').trim();
        st.inf = {
            erreur:'', connue:connue,
            plaque: connue ? d.plaque : 'PLAQUE NON LUE',
            type:   String(d.type||'SENS INTERDIT').replace(/_/g,' ').toUpperCase(),
            date:   String(d.horodatage||'').replace('T',' ').substring(0,19),
            carte:  o.carte_grise||'-',
            owner:  connue ? ((o.nom||'-')+' '+(o.prenom||'')).trim() : 'Inconnu',
            email:  o.email||'-',
            tel:    o.telephone||'-',
            lat:    la, lng: lo, adresse: adr,
            lien:   (la!==null) ? 'https://www.google.com/maps?q='+la+','+lo : '',
            conf:   (function(){
                        var v = [d.confiance, d.confidence, d.score, d.precision];
                        for (var k = 0; k < v.length; k++) {
                            var x = parseFloat(v[k]);
                            if (!isNaN(x)) return x <= 1 ? x * 100 : x;
                        }
                        return null;
                    })()
        };
    }
} else { return null; }

st.ts = Date.now();
context.set('st', st);
return {payload: Object.assign({}, st)};

if (msg.cmd === 'led') return [msg, null];
if (msg.cmd === 'cam') return [null, msg];
return null;
